+import fs from 'node:fs';
+import path from 'node:path';
+import assert from 'node:assert/strict';
+const dir = path.dirname(new URL(import.meta.url).pathname.replace(/^\/(\w:)/, '$1'));
+const read = name => JSON.parse(fs.readFileSync(path.join(dir, 'evidence', name + '.json'), 'utf8'));
+const payments = read('payment-api').entries.filter(e => e.message === 'Payment recorded');
+const reminders = read('reminder-worker').entries.filter(e => e.message === 'Reminder sent').sort((a,b) => a.ts.localeCompare(b.ts));
+const assessed = reminders.map(reminder => {
+  const payment = payments.filter(p => p.context.invoice === reminder.context.invoice && p.ts <= reminder.ts).sort((a,b) => b.ts.localeCompare(a.ts))[0];
+  return { invoice: reminder.context.invoice, reminderAt: reminder.ts, requestId: reminder.requestId,
+    statusSource: reminder.context.statusSource, latestPriorPayment: payment?.requestId ?? null,
+    latestPriorPaymentAt: payment?.ts ?? null, balanceDueMinor: payment?.context.balanceDueMinor ?? null,
+    wrongful: payment?.context.invoiceStatusAfter === 'PAID' && payment.context.balanceDueMinor === 0 };
+});
+const wrongful = assessed.filter(x => x.wrongful);
+const affected = [...new Set(wrongful.map(x => x.invoice))].sort();
+assert.deepEqual(affected, ['INV-CPL-1101','INV-CPL-1104','INV-CPL-1106','INV-CPL-1107','INV-CPL-1108']);
+assert.equal(wrongful.length, 6);
+assert.equal(wrongful[0].requestId, 'rem-CPL-91d2');
+const release = read('deploy').entries.find(e => e.context.changes?.some(c => c.includes('read invoice status from status-cache')));
+assert.equal(release.context.release, 'rel-20261027-2');
+assert.equal(release.context.flags['reminders.statusFromCache'], true);
+const answer = {
+  schemaVersion: 1, backlogId: 'PI-01', status: 'DONE',
+  evidenceFiles: ['deploy.json','payment-api.json','reminder-worker.json','status-cache.json','support-desk.json','kb-incident-rules.json','correlation.json','verification.txt'].map(f => 'evidence/' + f),
+  rootCauseRelease: release.context.release, rootCauseComponent: 'reminder-worker', containmentFlag: 'reminders.statusFromCache',
+  affectedInvoices: affected, firstWrongfulReminderRequestId: wrongful[0].requestId,
+  incidentRecord: {
+    impact: 'Six wrongful reminder emails affected five already-paid invoices: ' + affected.join(', ') + '. INV-CPL-1106 received two. No evidence of lost payments or incorrect ledger balances.',
+    timeline: [
+      '2026-10-27T05:58:02Z: status-cache refreshed snap-20261027-0558 on a six-hour schedule.',
+      '2026-10-27T06:05:40Z: rel-20261027-2 deployed reminder-worker reading cached status with reminders.statusFromCache=true; restarted 06:06:15Z.',
+      '2026-10-27T06:42:10Z: INV-CPL-1101 became PAID; at 07:10:05Z INV-CPL-1106 became PAID.',
+      '2026-10-27T07:40:01Z: rem-CPL-91d2 sent the first wrongful reminder for INV-CPL-1106; rem-CPL-7f3a followed for INV-CPL-1101 at 07:40:03Z.',
+      '2026-10-27T07:55:41Z, 08:30:12Z, 09:05:03Z: INV-CPL-1104, INV-CPL-1107 and INV-CPL-1108 respectively became PAID.',
+      '2026-10-27T08:45:00Z: rel-20261027-4 exposed cache age metrics; it did not introduce the cache consumer change.',
+      '2026-10-27T09:40:00Z: worker reused the 05:58 snapshot, ageSeconds=13078; the batch wrongly reminded INV-CPL-1104, INV-CPL-1107, INV-CPL-1108 and INV-CPL-1106.',
+      '2026-10-27T10:05:30Z: support escalated; log correlation identifies affected records beyond reported complaints.'
+    ],
+    rootCause: 'rel-20261027-2 changed reminder-worker from authoritative ledger database reads to a status-cache snapshot refreshed every six hours. Payments after 05:58 were correctly recorded PAID with zero balance but the worker reused stale OVERDUE statuses at 07:40 and 09:40. The root-cause component is reminder-worker, not the later status-cache metrics release. The payment-api webhook retry for INV-CPL-1108 completed before its wrongful reminder and is not the cause.',
+    containment: 'Recommended immediate action: switch reminders.statusFromCache OFF to restore authoritative database status reads. Pause queued reminder sends until eligibility is revalidated against current ledger status and positive balance. Do not roll back database changes. This report does not claim the production flag was changed.',
+    recovery: 'Reconcile every reminder with payments as of its send time, cancel queued reminders for the five affected invoices, contact affected clients with corrections, and verify future batches exclude PAID/zero-balance invoices. Preserve ledger/payment history and do not replay already-sent emails. INV-CPL-1102 and INV-CPL-1109 had positive balances; INV-CPL-1103 was paid only at 10:02 after both reminders, and INV-CPL-1105 was paid after its previous-day reminder: exclude them.',
+    prevention: 'Revalidate status and balance from the ledger immediately before sending; invalidate cached invoice status on payment commits and enforce a fail-closed freshness threshold with database fallback. Add chronology-based regressions for payment-before-send, payment-after-send, partial balance, duplicate batches and delayed webhook retries. Alert on reminders for PAID invoices and cache age above the freshness budget.'
+  }
+};
+const schema = JSON.parse(fs.readFileSync(path.join(dir, '../../challenge/PI-01-submit.schema.json'), 'utf8'));
+assert.deepEqual(Object.keys(answer).sort(), schema.required.slice().sort());
+for (const ref of answer.evidenceFiles) assert.match(ref, /^evidence\/[A-Za-z0-9][A-Za-z0-9._-]*$/);
+fs.writeFileSync(path.join(dir, 'evidence/correlation.json'), JSON.stringify({assessed, wrongfulCount:wrongful.length, affectedInvoices:affected},null,2)+'\n');
+fs.writeFileSync(path.join(dir, 'evidence/verification.txt'), `Chronological correlation verified: ${assessed.length} reminders, ${wrongful.length} wrongful sends, ${affected.length} affected invoices.\nFirst wrongful request: ${wrongful[0].requestId}\nRoot cause: ${answer.rootCauseRelease} / ${answer.rootCauseComponent}\nContainment flag to switch OFF: ${answer.containmentFlag}\nTop-level schema keys and evidence path format validated.\n`);
+for (const ref of answer.evidenceFiles) assert.ok(fs.existsSync(path.join(dir,ref)));
+fs.writeFileSync(path.join(dir,'submit.json'),JSON.stringify(answer,null,2)+'\n');
