+const dir=path.resolve('../answers/CR-01/evidence');
+const fixture=JSON.parse(fs.readFileSync(path.join(dir,'cr-01-test-data.json'),'utf8')).data;
+function parse(text) {
+  const rows=[]; let row=[],field='',quoted=false;
+  for(let i=0;i<text.length;i++) { const c=text[i];
+    if(c==='"') {if(quoted&&text[i+1]==='"'){field+='"';i++;}else quoted=!quoted;}
+    else if(c===','&&!quoted){row.push(field);field='';}
+    else if(c==='\n'&&!quoted){row.push(field.replace(/\r$/,''));rows.push(row);row=[];field='';}
+    else field+=c;
+  }
+  assert.equal(quoted,false); assert.equal(field,''); return rows;
+}
+const headers=['invoice_number','company','currency','issue_date','due_date','total','paid','balance_due','status'];
+const cases=[['tc-01-all-invoices.csv',null],['tc-02-filtered-invoices.csv','A'],['tc-03-special-company.csv','VN'],['tc-05-empty-export.csv','EMPTY']];
+const results=[];
+for(const [file,key] of cases){
+  const bytes=fs.readFileSync(path.join(dir,file)); assert.deepEqual([...bytes.subarray(0,3)],[239,187,191]);
+  const rows=parse(bytes.toString('utf8').slice(1));assert.deepEqual(rows.shift(),headers);
+  const expected=fixture.invoices.filter(i=>!key||i.company===key).sort((a,b)=>b.issueDate.localeCompare(a.issueDate)).map(i=>{
+    const company=fixture.companies.find(c=>c.key===i.company);const paid=i.payments.reduce((s,p)=>s+p.amountMinor,0);
+    const status=i.state==='ISSUED'?(paid>=i.totalMinor?'PAID':paid>0?'PARTIAL':'SENT'):i.state;
+    const balance=['SENT','PARTIAL','OVERDUE'].includes(status)?Math.max(0,i.totalMinor-paid):0;
+    const fmt=n=>['USD','EUR','GBP','AUD','CAD','SGD'].includes(company.currency)?(n/100).toFixed(2):String(n);
+    return [i.number,company.name,company.currency,i.issueDate,i.dueDate??'',fmt(i.totalMinor),fmt(paid),fmt(balance),status];
+  });
+  assert.deepEqual(rows,expected);results.push(`${file}: PASS (${rows.length} rows; BOM, columns, exact text, dates, currency amounts, payment sums, balances, status and order)`);
+}
+const auth=fs.readFileSync(path.join(dir,'tc-04-signed-out-request.txt'),'utf8');assert.ok(auth.includes('status: REJECTED'));assert.ok(auth.includes('invoice_data_leaked: no'));
+results.push('Signed-out request: REJECTED with no invoice data leaked.');
