+export interface AgingInvoice {
+  status: string;
+  currencyCode: string;
+  totalMinor: number;
+  paidMinor: number;
+  dueDate: string | null;
+}
+export const AGING_BUCKETS = ["current", "1-30", "31-60", "61-90", "90+"] as const;
+export interface AgingRow {
+  currency: string;
+  buckets: Record<(typeof AGING_BUCKETS)[number], number>;
+  totalMinor: number;
+}
+
+/** Open balances by UTC calendar day, never combining different currencies. */
+export function agingReport(invoices: AgingInvoice[], asOf: string): AgingRow[] {
+  const rows = new Map<string, AgingRow>();
+  const asOfDay = Date.parse(`${asOf}T00:00:00Z`);
+  for (const invoice of invoices) {
+    if (!["SENT", "PARTIAL", "OVERDUE"].includes(invoice.status)) continue;
+    const balance = Math.max(0, invoice.totalMinor - invoice.paidMinor);
+    if (balance <= 0) continue;
+    const days = invoice.dueDate === null ? 0
+      : Math.floor((asOfDay - Date.parse(`${invoice.dueDate}T00:00:00Z`)) / 86400000);
+    const bucket = days <= 0 ? "current" : days <= 30 ? "1-30"
+      : days <= 60 ? "31-60" : days <= 90 ? "61-90" : "90+";
+    const currency = invoice.currencyCode;
+    let row = rows.get(currency);
+    if (!row) {
+      row = { currency, buckets: { current: 0, "1-30": 0, "31-60": 0, "61-90": 0, "90+": 0 }, totalMinor: 0 };
+      rows.set(currency, row);
+    }
+    row.buckets[bucket] += balance;
+    row.totalMinor += balance;
+  }
+  return [...rows.values()].sort((a, b) => a.currency.localeCompare(b.currency));
+}
